#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    long long minNumberOfSeconds(int mountainHeight, std::vector<int>& workerTimes) {
        auto check = [&](long long seconds) {
            long long total_h = 0;
            for (int t : workerTimes) {
                long long val = (2 * seconds) / t;
                long long x = (std::sqrt(1 + 4.0 * val) - 1) / 2;
                total_h += x;
                if (total_h >= mountainHeight) return true;
            }
            return false;
        };

        long long low = 1;
        long long min_w = *std::min_element(workerTimes.begin(), workerTimes.end());
        long long high = min_w * (long long)mountainHeight * (mountainHeight + 1) / 2;
        long long ans = high;

        while (low <= high) {
            long long mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long minNumberOfSeconds(int mountainHeight, int[] workerTimes) {
        long minW = workerTimes[0];
        for (int t : workerTimes) minW = Math.min(minW, t);

        long low = 1;
        long high = minW * (long) mountainHeight * (mountainHeight + 1) / 2;
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (check(mid, mountainHeight, workerTimes)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean check(long seconds, int mountainHeight, int[] workerTimes) {
        long totalH = 0;
        for (int t : workerTimes) {
            long val = (2 * seconds) / t;
            long x = (long) ((Math.sqrt(1 + 4.0 * val) - 1) / 2);
            totalH += x;
            if (totalH >= mountainHeight) return true;
        }
        return false;
    }
}

var minNumberOfSeconds = function(mountainHeight, workerTimes) {
    function check(seconds) {
        let totalH = 0n;
        const target = BigInt(mountainHeight);
        for (const t of workerTimes) {
            const val = (2n * seconds) / BigInt(t);
            // Integer square root
            let s = 0n, e = 2000000000n, x = 0n;
            while (s <= e) {
                const m = (s + e) / 2n;
                if (m * (m + 1n) <= val) {
                    x = m;
                    s = m + 1n;
                } else {
                    e = m - 1n;
                }
            }
            totalH += x;
            if (totalH >= target) return true;
        }
        return false;
    }

    let minW = BigInt(workerTimes[0]);
    for (const t of workerTimes) {
        const bt = BigInt(t);
        if (bt < minW) minW = bt;
    }

    const mh = BigInt(mountainHeight);
    let low = 1n;
    let high = minW * mh * (mh + 1n) / 2n;
    let ans = high;

    while (low <= high) {
        const mid = (low + high) / 2n;
        if (check(mid)) {
            ans = mid;
            high = mid - 1n;
        } else {
            low = mid + 1n;
        }
    }
    return Number(ans);
};
